const items = $input.all();
const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let rows = items.map((it, i) => {
  const j = it.json;
  let src = 'AI News';
  try { src = new URL(j.link).hostname.replace(/^www\./, ''); } catch (e) {}
  const desc = esc(j.contentSnippet || j.description || '').substring(0, 220);
  return '<div style="margin-bottom:20px">'
    + '<div style="font-size:12px;color:#888;letter-spacing:1px">' + (i+1) + ' &middot; ' + esc(src.toUpperCase()) + '</div>'
    + '<a href="' + esc(j.link) + '" style="font-size:17px;font-weight:bold;color:#0a66c2;text-decoration:none">' + esc(j.title) + '</a>'
    + '<p style="color:#444;font-size:14px;line-height:1.5;margin:6px 0 0">' + desc + '...</p></div>';
}).join('');
const date = new Date().toDateString();
const html = '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto">'
  + '<h2 style="color:#111">&#129302; Daily AI Digest &mdash; ' + esc(date) + '</h2>'
  + '<p style="color:#666;font-size:13px">' + items.length + ' top AI stories, curated automatically.</p><hr style="border:none;border-top:1px solid #eee">'
  + rows
  + '<hr style="border:none;border-top:1px solid #eee"><p style="color:#999;font-size:12px">Built with n8n by Fahad Khan</p></div>';
return [{ json: { html, count: items.length, date } }];
